INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_APSYSTEMS', 'TIPOPROTOCOLLAZIONE', 'Questo parametro determina se una protocollazione in partenza deve chiamare il metodo InsertProtocolloGenerale o InsertBozzaProtocolloInterno, nel primo caso infatti il ws non notifica all''ufficio la creazione del protocollo, nel secondo caso invece si. Si è creato questo parametro per compatibilità con la precedente logica. Impostare a 1 se si desidera utilizzare la nuova logica di notifica anche all''ufficio, non valorizzare se si desidera mantenere il comportamento precedente.');
